//! Generates outer and alternate end entity certificates per draft-davidben-lamps-turducken-certs-00
//!
//! The outer certificates are the stock PKITS end entity certificates, re-signed by the stock RSA
//! CA keys after their extensions are reordered and an embedded SCT extension carrying an
//! AlternateIssuerInfo is appended. The alternate certificates certify the same subject and RSA
//! subject key and are signed by the CA keys from a set generated by this tool (e.g., ML-DSA-65),
//! with an outer certificate binding extension appended.
//!
//! The generated set must be produced without a `name_suffix`, so that the names in name
//! constraints and CRL distribution points match the stock ones and each alternate shares the
//! subject name of its outer certificate. A `ca_name_suffix` gives its CAs distinct names, and
//! `regenerate_key_identifiers` distinct key identifiers, so neither set's CAs are candidate
//! issuers for the other set's certificates.

use std::{ffi::OsStr, fs, path::Path};

use const_oid::{ObjectIdentifier, db::rfc5280, db::rfc6962::CT_PRECERT_SCTS};
use der::{
    Decode, Encode, Sequence,
    asn1::{BitString, OctetString},
};
use log::{error, info};
use rsa::{PrivateKey, pkcs1v15::SigningKey, pkcs8::DecodePrivateKey};
use sha2::Sha256;
use signature::Signer;
use spki::{AlgorithmIdentifierOwned, SignatureBitStringEncoding};
use walkdir::WalkDir;
use x509_cert::{TbsCertificate, ext::Extension, name::Name, serial_number::SerialNumber};

use pkcs12_builder::asn1_utils::parse_pkcs12;

use crate::{
    Error, Result,
    generation::settings::GenerationSettings,
    misc::utils::{get_file_as_byte_vec, get_file_as_cert},
    storage::{
        asn1::{DeferDecodeSigned, FakeCertificate, FakeTbsCertificate, get_akid},
        settings::StorageSettings,
    },
};

/// Placeholder for TBD3, the `alternate_issuer_info` VersionedTransType. 0xE000 is the first value
/// in the Experimental Use range of the RFC 9162 VersionedTransTypes registry.
pub const ALTERNATE_ISSUER_INFO_TYPE: u16 = 0xE000;

/// Placeholder for TBD2, id-pe-outerCertificateBinding.
pub const ID_PE_OUTER_CERTIFICATE_BINDING: ObjectIdentifier =
    ObjectIdentifier::new_unwrap("1.3.6.1.5.5.7.1.99");

/// Password protecting the stock PKITS PKCS #12 files.
const PKITS_P12_PASSWORD: &str = "password";

/// Extensions placed after the common extensions, i.e., those that differ by issuer. All others,
/// including certificate policies, are common.
const ISSUER_SPECIFIC_EXTENSIONS: [ObjectIdentifier; 5] = [
    rfc5280::ID_CE_AUTHORITY_KEY_IDENTIFIER,
    rfc5280::ID_CE_CRL_DISTRIBUTION_POINTS,
    rfc5280::ID_CE_FRESHEST_CRL,
    rfc5280::ID_CE_ISSUER_ALT_NAME,
    rfc5280::ID_PE_AUTHORITY_INFO_ACCESS,
];

/// ```text
/// AlternateIssuerInfo ::= SEQUENCE {
///     serialNumber         CertificateSerialNumber,
///     signatureAlgorithm   AlgorithmIdentifier{SIGNATURE-ALGORITHM,
///                              {SignatureAlgorithms}},
///     issuer               Name,
///     commonExtensionCount INTEGER (0..MAX),
///     issuerExtensions     SEQUENCE OF Extension{{CertExtensions}},
///     signatureValue       BIT STRING
/// }
/// ```
#[derive(Clone, Debug, Eq, PartialEq, Sequence)]
#[allow(missing_docs)]
pub struct AlternateIssuerInfo {
    pub serial_number: SerialNumber,
    pub signature_algorithm: AlgorithmIdentifierOwned,
    pub issuer: Name,
    pub common_extension_count: u32,
    pub issuer_extensions: Vec<Extension>,
    pub signature_value: BitString,
}

/// ```text
/// OuterCertificateBinding ::= SEQUENCE {
///     serialNumber         CertificateSerialNumber,
///     signatureAlgorithm   AlgorithmIdentifier{SIGNATURE-ALGORITHM,
///                             {SignatureAlgorithms}},
///     issuer               Name,
///     commonExtensionCount INTEGER (0..MAX),
///     issuerExtensions     SEQUENCE OF Extension{{CertExtensions}}
/// }
/// ```
#[derive(Clone, Debug, Eq, PartialEq, Sequence)]
#[allow(missing_docs)]
pub struct OuterCertificateBinding {
    pub serial_number: SerialNumber,
    pub signature_algorithm: AlgorithmIdentifierOwned,
    pub issuer: Name,
    pub common_extension_count: u32,
    pub issuer_extensions: Vec<Extension>,
}

/// Splits `extensions` into common and issuer-specific extensions, each in their original order.
fn partition_extensions(extensions: &[Extension]) -> (Vec<Extension>, Vec<Extension>) {
    extensions
        .iter()
        .cloned()
        .partition(|e| !ISSUER_SPECIFIC_EXTENSIONS.contains(&e.extn_id))
}

/// Appends `data` to `out` preceded by its length as a two-byte big-endian value.
fn push_u16_prefixed(out: &mut Vec<u8>, data: &[u8]) -> Result<()> {
    let len = u16::try_from(data.len()).map_err(|_| Error::Unrecognized)?;
    out.extend_from_slice(&len.to_be_bytes());
    out.extend_from_slice(data);
    Ok(())
}

/// Returns an embedded SCT extension whose SignedCertificateTimestampList holds one TransItem of
/// type alternate_issuer_info for each of `infos`.
fn embedded_sct_extension(infos: &[AlternateIssuerInfo]) -> Result<Extension> {
    let mut sct_list = vec![];
    for info in infos {
        let mut trans_item = ALTERNATE_ISSUER_INFO_TYPE.to_be_bytes().to_vec();
        push_u16_prefixed(&mut trans_item, &info.to_der()?)?;
        push_u16_prefixed(&mut sct_list, &trans_item)?;
    }
    let mut list = vec![];
    push_u16_prefixed(&mut list, &sct_list)?;
    // extnValue holds a DER-encoded OCTET STRING containing the list
    Ok(Extension {
        extn_id: CT_PRECERT_SCTS,
        critical: false,
        extn_value: OctetString::new(OctetString::new(list)?.to_der()?)?,
    })
}

/// Returns the outer certificate binding extension for `binding`.
fn binding_extension(binding: &OuterCertificateBinding) -> Result<Extension> {
    Ok(Extension {
        extn_id: ID_PE_OUTER_CERTIFICATE_BINDING,
        critical: false,
        extn_value: OctetString::new(binding.to_der()?)?,
    })
}

/// Returns a copy of `tbs` with `signature` as the signature algorithm and `extensions` as the
/// extensions.
fn tbs_with(
    tbs: &TbsCertificate,
    signature: &AlgorithmIdentifierOwned,
    extensions: Vec<Extension>,
) -> FakeTbsCertificate {
    FakeTbsCertificate {
        version: tbs.version(),
        serial_number: tbs.serial_number().clone(),
        signature: signature.clone(),
        issuer: tbs.issuer().clone(),
        validity: *tbs.validity(),
        subject: tbs.subject().clone(),
        subject_public_key_info: tbs.subject_public_key_info().clone(),
        issuer_unique_id: None,
        subject_unique_id: None,
        extensions: Some(extensions),
    }
}

/// Signs `tbs` with the RSA key in `p12_file`, corrupting the signature if `good` is false. The
/// stock PKITS PKCS #12 files use legacy algorithms, which require the `legacy_p12` feature.
fn rsa_sign(p12_file: &Path, tbs: &[u8], good: bool) -> Result<BitString> {
    let contents = parse_pkcs12(&get_file_as_byte_vec(p12_file)?, PKITS_P12_PASSWORD)?;
    let private_key = PrivateKey::from_pkcs8_der(&contents.key_der).map_err(|_| Error::Rsa)?;
    let signing_key = SigningKey::<Sha256>::new(private_key);
    let mut sig = signing_key
        .try_sign(tbs)
        .map_err(|_| Error::Rsa)?
        .to_bitstring()?
        .raw_bytes()
        .to_vec();
    if !good && let Some(last) = sig.last_mut() {
        *last ^= 0xFF;
    }
    Ok(BitString::from_bytes(&sig)?)
}

/// Generates the outer and alternate certificates for the end entity certificate in `ee_path`
/// and returns them, DER-encoded, in that order. `alt_ee_path` is the generated counterpart of
/// `ee_path`, which supplies the alternate's issuer-specific extensions.
fn generate_pair(
    ee_path: &Path,
    alt_ee_path: &Path,
    alt_storage: &StorageSettings,
    outer_keys_folder: &Path,
) -> Result<(Vec<u8>, Vec<u8>)> {
    let orig_path = ee_path.to_str().unwrap_or_default();
    let ee = get_file_as_cert(ee_path)?;
    let akid = get_akid(&ee)?;
    let defer = DeferDecodeSigned::from_der(&get_file_as_byte_vec(ee_path)?)?;
    let good = alt_storage.orig_signature_verifies(&akid, &defer)?;
    let tbs = TbsCertificate::from_der(&defer.tbs_field)?;

    let (common, issuer_specific) =
        partition_extensions(tbs.extensions().map(|e| e.as_slice()).unwrap_or_default());
    let common_extension_count = u32::try_from(common.len()).map_err(|_| Error::Unrecognized)?;
    let outer_alg = tbs.signature().clone();

    // Alternate: same subject information, signed by the generated CA key, ending with a binding
    // to the outer certificate's issuer-specific fields. Its issuer name and its own
    // issuer-specific extensions, e.g., an AKID identifying the generated CA key, come from the
    // generated end entity certificate. The generated set reuses the stock serial numbers.
    let alt_ee = get_file_as_cert(alt_ee_path)?;
    let (_, alt_issuer_specific) = partition_extensions(
        alt_ee
            .tbs_certificate()
            .extensions()
            .map(|e| e.as_slice())
            .unwrap_or_default(),
    );
    let (alt_ca_spki, alt_signer) = alt_storage.load_signer(&akid)?;
    let alt_alg = alt_ca_spki.algorithm;
    let binding = OuterCertificateBinding {
        serial_number: tbs.serial_number().clone(),
        signature_algorithm: outer_alg.clone(),
        issuer: tbs.issuer().clone(),
        common_extension_count,
        issuer_extensions: issuer_specific.clone(),
    };
    let mut alt_extensions = common.clone();
    alt_extensions.extend(alt_issuer_specific.iter().cloned());
    alt_extensions.push(binding_extension(&binding)?);
    let alt_issuer = alt_ee.tbs_certificate().issuer().clone();
    let mut alt_tbs = tbs_with(&tbs, &alt_alg, alt_extensions);
    alt_tbs.issuer = alt_issuer.clone();
    let alt_signature = StorageSettings::sign(&alt_signer, &alt_tbs.to_der()?, good)?;
    let alt_cert = FakeCertificate {
        tbs_certificate: alt_tbs,
        signature_algorithm: alt_alg.clone(),
        signature: alt_signature.clone(),
    }
    .to_der()?;

    // Outer: the stock TBS with reordered extensions and the alternate appended as an SCT.
    let info = AlternateIssuerInfo {
        serial_number: tbs.serial_number().clone(),
        signature_algorithm: alt_alg,
        issuer: alt_issuer,
        common_extension_count,
        issuer_extensions: alt_issuer_specific,
        signature_value: alt_signature,
    };
    let mut outer_extensions = common;
    outer_extensions.extend(issuer_specific);
    outer_extensions.push(embedded_sct_extension(&[info])?);
    let outer_tbs = tbs_with(&tbs, &outer_alg, outer_extensions);
    let p12_file =
        outer_keys_folder.join(format!("{}.p12", alt_storage.get_file_name_for_skid(&akid)));
    let outer_signature = rsa_sign(&p12_file, &outer_tbs.to_der()?, good)?;
    let outer_cert = FakeCertificate {
        tbs_certificate: outer_tbs,
        signature_algorithm: outer_alg,
        signature: outer_signature,
    }
    .to_der()?;

    if !good {
        info!("Reproduced bad signature on outer and alternate for {orig_path}");
    }
    Ok((outer_cert, alt_cert))
}

/// Generates an outer and alternate certificate for each end entity certificate in `certs_folder`
/// and writes them to the `outer` and `alternate` folders in `output_folder`. Alternate CA keys
/// come from the `keys` folder of `alt_folder`, which was generated from `certs_folder` per
/// `generation_settings`, and outer CA keys from the PKCS #12 files in `outer_keys_folder`. The
/// alternates' issuer-specific extensions come from the end entity certificates in the `certs`
/// folder of `alt_folder`.
pub fn generate(
    certs_folder: &str,
    alt_folder: &str,
    outer_keys_folder: &str,
    output_folder: &str,
    generation_settings: &GenerationSettings,
) -> Result<usize> {
    // Index the source certificates as ingest does, so key lookups find the same files
    let mut alt_storage = StorageSettings::new(alt_folder);
    let mut ees = vec![];
    for entry in WalkDir::new(certs_folder).into_iter().flatten() {
        let path = entry.path();
        if !entry.file_type().is_file()
            || !matches!(
                path.extension().and_then(OsStr::to_str),
                Some("der" | "crt" | "cer")
            )
        {
            continue;
        }
        let Ok(cert) = get_file_as_cert(path) else {
            continue;
        };
        let orig_path = path.to_str().unwrap_or_default();
        if generation_settings.get_target(&cert, orig_path).is_err() {
            continue;
        }
        alt_storage.record_skid(&cert, orig_path)?;
        if path
            .file_stem()
            .and_then(OsStr::to_str)
            .is_some_and(|s| s.ends_with("EE"))
        {
            ees.push(path.to_path_buf());
        }
    }

    let outer_dir = Path::new(output_folder).join("outer");
    let alt_dir = Path::new(output_folder).join("alternate");
    fs::create_dir_all(&outer_dir)?;
    fs::create_dir_all(&alt_dir)?;

    let mut counter = 0;
    for ee_path in ees {
        let Some(stem) = ee_path.file_stem().and_then(OsStr::to_str) else {
            continue;
        };
        let alt_ee_path = Path::new(alt_folder)
            .join("certs")
            .join(format!("{stem}.der"));
        match generate_pair(
            &ee_path,
            &alt_ee_path,
            &alt_storage,
            Path::new(outer_keys_folder),
        ) {
            Ok((outer, alt)) => {
                fs::write(outer_dir.join(format!("{stem}.der")), outer)?;
                fs::write(alt_dir.join(format!("{stem}.der")), alt)?;
                counter += 1;
            }
            Err(e) => error!(
                "Failed to generate turducken pair for {}: {e:?}",
                ee_path.display()
            ),
        }
    }
    Ok(counter)
}
